mapper.sql:
WHERE l.EFFECTIVE_TO_DTM IS NULL

   AND p.PRODUCT_ID = #{productId}


   AND v.VERSION_ID = #{versionId}


   AND p.RESOURCE_TYPE_CD = #{resourceTypeCd}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT p.PRODUCT_ID, p.PRODUCT_NAME, p.RESOURCE_TYPE_CD,
           v.VERSION_ID, v.VERSION_NO,
           l.LFC_ID, l.GA_YMD, l.EOS_YMD, l.EOL_YMD, l.EFFECTIVE_FROM_DTM, l.EVIDENCE_ID, l.SOURCE_DESC
      FROM TB_EOS_PRODUCT_LFC l
      JOIN TB_EOS_PRODUCT_VER v ON v.VERSION_ID = l.VERSION_ID
      JOIN TB_EOS_PRODUCT p ON p.PRODUCT_ID = v.PRODUCT_ID

     ORDER BY p.PRODUCT_NAME, v.VERSION_NO
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

mapper.update:
UPDATE TB_EOS_PRODUCT_LFC
   SET EFFECTIVE_TO_DTM = #{effectiveToDtm}
 WHERE LFC_ID = #{lfcId}
   AND EFFECTIVE_TO_DTM IS NULL

mapper.insert:
