) VALUES (
    #{lfcId}, #{versionId}, #{gaYmd}, #{eosYmd}, #{eolYmd}, #{evidenceId}, #{sourceDesc},
    #{effectiveFromDtm}, #{changeReason}, #{regUserId}, #{regDtm}
