UPDATE TB_EOS_RESOURCE
   SET EOS_STATUS_CD = #{eosStatusCd},
       CHG_USER_ID = #{chgUserId},
       CHG_DTM = #{chgDtm}
 WHERE RESOURCE_ID = #{resourceId}
